const item = $input.first().json;
const body = item.body && item.body.requestId ? item.body : item;
if (body.capability && body.capability !== 'hub.discover') {
  return [{ json: { protocolVersion: 1, requestId: body.requestId, status: 'error', data: null, sources: [], warnings: [], error: { code: 'capability_unavailable', message: 'This workflow only serves hub.discover' }, duration: 1 } }];
}
const capabilities = [{"name":"hub.health","description":"Echo a short token and report hub health"},{"name":"research.problem","description":"Gather short evidence for a problem. Returns sources and excerpts, not a workspace edit."},{"name":"knowledge.lookup","description":"Find a prior note by query, or remember a short note. Does not read the workspace."},{"name":"task.decompose","description":"Split a large goal into a bounded task graph for one step at a time."}];
return [{ json: { protocolVersion: 1, requestId: body.requestId, status: 'ok', data: { capabilities }, sources: [], warnings: [], error: null, duration: 1 } }];
